export function evaluate({ inputs, time }) {
  const u = inputs.launchSpeed;
  const g = inputs.gravity;
  const m = inputs.mass;

  const tTop = u / g;
  const yTop = (u * u) / (2 * g);
  const duration = 2 * tTop;
  const tClamped = Math.max(0, Math.min(time, duration));

  const v = u - g * tClamped;
  const y = u * tClamped - 0.5 * g * tClamped * tClamped;
  const a = -g;
  const F = m * g;

  let stateText = 'At the top';
  if (tClamped < 0.001) {
    stateText = 'Ready to toss';
  } else if (tClamped < tTop - 0.02) {
    stateText = 'Rising';
  } else if (tClamped > tTop + 0.02 && tClamped < duration - 0.001) {
    stateText = 'Falling';
  } else if (tClamped >= duration - 0.001) {
    stateText = 'Back at launch height';
  }

  const objects = [];

  const leftPanel = sdk.panel({
    x: 10,
    y: 30,
    w: 305,
    h: 380,
    title: 'The motion',
    state: stateText,
    id: 'lane.motion'
  });
  objects.push(...leftPanel);

  const rightPanel = sdk.panel({
    x: 325,
    y: 30,
    w: 305,
    h: 380,
    title: 'Velocity over time',
    state: `a = -${g.toFixed(1)} m/s²`,
    id: 'lane.graph'
  });
  objects.push(...rightPanel);

  const axisH = 300;
  const axisX = 85;
  const axisY = 90;

  objects.push(
    sdk.axis('axis.height', {
      x: axisX,
      y: axisY + axisH,
      length: axisH,
      orientation: 'y',
      min: 0,
      max: 2.2,
      ticks: 5,
      label: 'Height',
      unit: 'm'
    })
  );

  const ballYPx = axisY + axisH - (y / 2.2) * axisH;
  const ballXPx = axisX + 70;

  objects.push(
    sdk.circle('ball.toss', ballXPx, ballYPx, 26, {
      role: 'learner'
    })
  );

  const vVec = sdk.vector(
    'vec.v',
    { x: ballXPx - 20, y: ballYPx },
    {
      value: v,
      direction: 'up',
      scale: 12,
      minLength: 8,
      label: 'v',
      role: 'output'
    }
  );
  objects.push(...vVec);

  const aVec = sdk.vector(
    'vec.a',
    { x: ballXPx + 20, y: ballYPx },
    {
      value: a,
      direction: 'up',
      scale: 10,
      minLength: 8,
      label: 'a',
      role: 'warning'
    }
  );
  objects.push(...aVec);

  const calloutLines = [
    `v = ${v >= 0 ? '+' : ''}${v.toFixed(2)} m/s`,
    `a = ${a.toFixed(1)} m/s²`,
    `Fg = ${F.toFixed(1)} N (down)`
  ];
  const calloutObj = sdk.callout(ballXPx + 35, ballYPx - 25, calloutLines, {
    id: 'callout.toss',
    role: 'neutral'
  });
  objects.push(...calloutObj);

  const plotX = 385;
  const plotY = 90;
  const plotW = 230;
  const plotH = 290;

  const numPoints = 24;
  const linePoints = [];
  for (let i = 0; i <= numPoints; i++) {
    const tp = (duration * i) / numPoints;
    const vp = u - g * tp;
    linePoints.push({ x: tp, y: vp });
  }

  const tracePoints = [];
  const stepCount = Math.min(24, Math.max(2, Math.floor((tClamped / duration) * 24)));
  for (let i = 0; i <= stepCount; i++) {
    const tp = (tClamped * i) / stepCount;
    const vp = u - g * tp;
    tracePoints.push({ x: tp, y: vp });
  }

  const plotObj = sdk.plot('plot.vt', {
    x: plotX,
    y: plotY,
    w: plotW,
    h: plotH,
    axes: {
      x: { label: 'Time', min: 0, max: 1.8, unit: 's' },
      y: { label: 'Velocity', min: -5.5, max: 5.5, unit: 'm/s' }
    },
    series: [
      { label: 'v(t) ideal', kind: 'line', points: linePoints },
      { label: 'v(t) current', kind: 'line', points: tracePoints }
    ]
  });
  objects.push(plotObj);

  return {
    frame: {
      width: 640,
      height: 420,
      objects,
      readouts: [
        { id: 'velocity', value: v },
        { id: 'acceleration', value: a },
        { id: 'force', value: F },
        { id: 'motionState', value: stateText }
      ]
    },
    quantities: {
      launchSpeed: u,
      gravity: g,
      mass: m,
      apexTime: tTop,
      apexHeight: yTop,
      height: y,
      velocity: v,
      acceleration: a,
      force: F
    }
  };
}
